import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            if (i > 0) {
                sb.append("、");
            }
            sb.append(x);
        }
        String line = sb.toString();
        System.out.println("今天到了 " + n + " 个号：" + line);
        System.out.println("这串项链有 " + line.length() + " 个字");
    }
}

